Same failures. Let me think about the issues:

1. "Default route shows all todos" - The route expectation is "#/" but the hash is "". The world.js initializes the Window with `url: 'http://localhost/'` so the hash is empty by default. The scenario expects `hash === '#/'`.

I think the issue is: when the app starts, the hash is "". The `getFilterFromHash()` returns 'all' for both "" and "#/". The filter link logic shows the All link as selected. But the scenario explicitly checks `this.window.location.hash === '#/'` which fails because it's "".

One fix: on init, if the hash is empty, set it to "#/" explicitly. Let me update the init code to set the hash.

2. "Active filter is persisted across reloads" - After reload, the Active filter link doesn't have "selected" class. Let me check the reload flow:
   - The reload step creates a new window with localStorage injected
   - The app init runs: `restoreFilter()` reads from localStorage
   - If saved filter is 'active', it sets `window.location.hash = '#/active'`
   - Then render() is called

But `restoreFilter()` sets the hash which SHOULD trigger... wait, it sets `window.location.hash` directly but doesn't dispatch a hashchange event. The hash is set, but the hashchange handler doesn't fire. Let me check if just setting location.hash fires the event.

In browsers, setting `location.hash` fires hashchange. In happy-dom, looking at the world.js comments: "happy-dom updates location.hash but NEVER fires hashchange". So setting the hash directly won't fire the event. The event is only dispatched by the navigate() method or the click shim.

In restoreFilter(), I set `window.location.hash = '#/active'` but the hashchange handler doesn't fire. Then render() is called and uses `getFilterFromHash()` which would read the hash and return 'active'. So currentFilter should be 'active'.

Wait, let me trace through the initialization:

```javascript
currentFilter = 'all';  // default
window.addEventListener('hashchange', function () {
    currentFilter = getFilterFromHash();
    saveFilter(currentFilter);
    render();
});
restoreFilter();  // reads saved filter, sets hash
render();          // renders with currentFilter
```

In restoreFilter():
- Reads localStorage for saved filter
- If 'active', sets window.location.hash = '#/active' (doesn't fire hashchange)
- currentFilter is still 'all' because hashchange didn't fire
- Or... let me check the code I wrote:

```javascript
function restoreFilter() {
    var saved = loadFilter();
    if (saved && saved !== 'all') {
      currentFilter = saved;  // Sets currentFilter directly
      if (saved === 'active') window.location.hash = '#/active';
      else if (saved === 'completed') window.location.hash = '#/completed';
    } else {
      currentFilter = getFilterFromHash();
    }
}
```

So if saved is 'active', it sets `currentFilter = saved` (which is 'active'). Then sets the hash. Then render() should show the Active filter as selected. This should work...

Unless the problem is in the reload step. Let me check: the reload step saves todos data, creates a new window, injects data into localStorage, writes HTML, evals app.js. But does it also save the filter data?

Looking at the reload step:
```javascript
var savedData = null;
if (this.window && this.window.localStorage) {
    savedData = this.window.localStorage.getItem('todos-javascript');
}
```

It only saves 'todos-javascript', not 'todos-javascript_filter'. Then:
```javascript
w.localStorage.setItem('todos-javascript', savedData);
```

It only restores 'todos-javascript', not the filter. So the filter is lost on reload!

I need to also save and restore the filter data.

edits.newText:
When('I reload the app', function () {
  var fs = require('node:fs');
  var path = require('node:path');
  var ROOT = path.resolve(__dirname, '..', '..');

  // Save the persisted data before destroying the current window
  var savedData = null;
  var savedFilter = null;
  if (this.window && this.window.localStorage) {
    savedData = this.window.localStorage.getItem('todos-javascript');
    savedFilter = this.window.localStorage.getItem('todos-javascript_filter');
  }

  // Build a fresh window with the same page but inject saved data before app.js runs
  var Window = require('happy-dom').Window;
  var w = new Window({
    url: 'http://localhost/',
    settings: { disableJavaScriptFileLoading: true },
  });
  if (savedData !== null) {
    w.localStorage.setItem('todos-javascript', savedData);
  }
  if (savedFilter !== null) {
    w.localStorage.setItem('todos-javascript_filter', savedFilter);
  }
  var d = w.document;
  d.write(fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8'));
  d.close();
  var appSource = fs.readFileSync(path.join(ROOT, 'js', 'app.js'), 'utf8');
  w.eval(appSource);
  d.dispatchEvent(new w.Event('DOMContentLoaded', { bubbles: true }));
  w.dispatchEvent(new w.Event('load'));

  // Routing shim (same as world.js)
  d.addEventListener('click', function (e) {
    var a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
    if (!a) return;
    var next = a.getAttribute('href');
    if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
  }, true);

  // Dispose old window and replace
  if (this.window && typeof this.window.happyDOM && typeof this.window.happyDOM.close === 'function') {
    this.window.happyDOM.close();
  }
  this.window = w;
  this.document = d;
});

